// Full optimized lifecycle flow: skip division read, skip employments[],
// combine account reads (1920+6590+2400), parallelize emp1+emp2+project in step 2
const BASE = "https://kkpqfuj-amager.tripletex.dev/v2";
const TOKEN = "eyJ0b2tlbklkIjoyMTQ3NjI4NDYxLCJ0b2tlbiI6IjU2NDRjNDljLWU0YzYtNGU2OC05MWU5LWU0MzBhMWRiYTMzYSJ9";
const AUTH = "Basic " + btoa("0:" + TOKEN);
const TODAY = "2026-03-21";
const RND = Math.floor(Math.random() * 100000);

let callCount = 0;
let errorCount = 0;

async function api(method: string, path: string, body?: any) {
  callCount++;
  const url = `${BASE}${path}`;
  const opts: any = {
    method,
    headers: { "Content-Type": "application/json", Authorization: AUTH },
  };
  if (body) opts.body = JSON.stringify(body);
  const r = await fetch(url, opts);
  const text = await r.text();
  let json: any;
  try { json = JSON.parse(text); } catch { json = text; }
  console.log(`[${callCount}] ${method} ${path} → ${r.status}`);
  if (r.status >= 400) {
    errorCount++;
    console.log("ERROR:", JSON.stringify(json).slice(0, 500));
    throw new Error(`${method} ${path} → ${r.status}`);
  }
  return json;
}

function splitHours(total: number, startDate: string): { date: string; hours: number }[] {
  const chunks: { date: string; hours: number }[] = [];
  const [y, m, d] = startDate.split("-").map(Number);
  let remaining = total;
  let offset = 0;
  while (remaining > 0) {
    const h = Math.min(remaining, 7.5);
    const dt = new Date(Date.UTC(y, m - 1, d + offset));
    chunks.push({ date: dt.toISOString().slice(0, 10), hours: h });
    remaining -= h;
    offset++;
  }
  return chunks;
}

async function main() {
  // Step 1: GET dept + POST customer + GET PM (3 parallel)
  // SKIP: GET /division (not needed if we omit employments[])
  console.log("=== Step 1: dept + customer + PM (3 parallel) ===");
  const [deptRes, custRes, pmRes] = await Promise.all([
    api("GET", "/department?isInactive=false&count=1&fields=*"),
    api("POST", "/customer", {
      name: `OptCust ${RND} AS`,
      organizationNumber: "857400526",
      isCustomer: true,
    }),
    api("GET", "/employee?assignableProjectManagers=true&count=1&fields=*"),
  ]);
  const deptId = deptRes.values[0].id;
  const customerId = custRes.value.id;
  const pmId = pmRes.values[0].id;

  // Step 2: emp1 + emp2 + project (3 parallel)
  // Employees: no employments[], just department
  console.log("=== Step 2: emp1 + emp2 + project (3 parallel) ===");
  const [emp1Res, emp2Res, projRes] = await Promise.all([
    api("POST", "/employee", {
      firstName: "OptCatarina",
      lastName: `Martins${RND}`,
      email: `optcat${RND}@example.org`,
      dateOfBirth: "1990-01-15",
      userType: "NO_ACCESS",
      department: { id: deptId },
    }),
    api("POST", "/employee", {
      firstName: "OptJoão",
      lastName: `Martins${RND}`,
      email: `optjoao${RND}@example.org`,
      dateOfBirth: "1992-06-20",
      userType: "NO_ACCESS",
      department: { id: deptId },
    }),
    api("POST", "/project", {
      name: `OptProject ${RND}`,
      startDate: TODAY,
      customer: { id: customerId },
      projectManager: { id: pmId },
    }),
  ]);
  const emp1Id = emp1Res.value.id;
  const emp2Id = emp2Res.value.id;
  const projectId = projRes.value.id;

  // Step 3: activity + participant x2 (3 parallel)
  console.log("=== Step 3: activity + part1 + part2 (3 parallel) ===");
  const [paRes] = await Promise.all([
    api("POST", "/project/projectActivity", {
      project: { id: projectId },
      startDate: TODAY,
      budgetFeeCurrency: 229500,
      activity: {
        name: "Prosjektaktivitet",
        activityType: "PROJECT_SPECIFIC_ACTIVITY",
        isChargeable: false,
      },
    }),
    api("POST", "/project/participant", {
      project: { id: projectId },
      employee: { id: emp1Id },
      adminAccess: false,
    }),
    api("POST", "/project/participant", {
      project: { id: projectId },
      employee: { id: emp2Id },
      adminAccess: false,
    }),
  ]);
  const activityId = paRes.value.activity.id;

  // Step 4: timesheet + supplier + combined accounts(1920,6590,2400) + voucherType (4 parallel)
  console.log("=== Step 4: timesheet + supplier + combined accounts + voucherType (4 parallel) ===");
  const emp1Chunks = splitHours(37, TODAY);
  const emp2Chunks = splitHours(62, TODAY);
  const timesheetEntries = [
    ...emp1Chunks.map(c => ({
      employee: { id: emp1Id },
      project: { id: projectId },
      activity: { id: activityId },
      date: c.date,
      hours: c.hours,
    })),
    ...emp2Chunks.map(c => ({
      employee: { id: emp2Id },
      project: { id: projectId },
      activity: { id: activityId },
      date: c.date,
      hours: c.hours,
    })),
  ];

  const [tsRes, suppRes, accRes, vtRes] = await Promise.all([
    api("POST", "/timesheet/entry/list", timesheetEntries),
    api("POST", "/supplier", {
      name: `OptOceano ${RND} Lda`,
      organizationNumber: "941830420",
      isSupplier: true,
    }),
    api("GET", "/ledger/account?number=1920,6590,2400&fields=id,number,name,isBankAccount,bankAccountNumber"),
    api("GET", "/ledger/voucherType?name=Leverand%C3%B8rfaktura&count=1&fields=id,name"),
  ]);

  const suppId = suppRes.value.id;
  const accounts = accRes.values;
  const acc1920 = accounts.find((a: any) => a.number === 1920);
  const acc6590 = accounts.find((a: any) => a.number === 6590);
  const acc2400 = accounts.find((a: any) => a.number === 2400);
  const voucherTypeId = vtRes.values[0].id;

  console.log("acc1920:", acc1920?.id, "bankAcctNum:", acc1920?.bankAccountNumber);
  console.log("acc6590:", acc6590?.id, "acc2400:", acc2400?.id, "vtId:", voucherTypeId);
  console.log("timesheet total:", tsRes.values.reduce((s: number, e: any) => s + e.hours, 0));

  // Step 5: voucher + vatType (2 parallel)
  // NO separate bank account read - already have acc1920 from combined read
  console.log("=== Step 5: voucher + vatType (2 parallel) ===");
  const [voucherRes, vatRes] = await Promise.all([
    api("POST", "/ledger/voucher", {
      date: TODAY,
      description: `OptOceano ${RND} - leverandørkostnad`,
      voucherType: { id: voucherTypeId },
      postings: [
        {
          row: 1,
          account: { id: acc6590!.id },
          amount: 56300,
          amountCurrency: 56300,
          amountGross: 56300,
          amountGrossCurrency: 56300,
          project: { id: projectId },
        },
        {
          row: 2,
          account: { id: acc2400!.id },
          amount: -56300,
          amountCurrency: -56300,
          amountGross: -56300,
          amountGrossCurrency: -56300,
          supplier: { id: suppId },
        },
      ],
    }),
    api("GET", `/ledger/vatType?typeOfVat=OUTGOING&vatDate=${TODAY}&fields=*`),
  ]);

  const vatType = vatRes.values.find((v: any) => v.percentage === 25.0) || vatRes.values[0];

  // Step 6: bank fix if needed (0-1)
  if (acc1920 && !acc1920.bankAccountNumber) {
    console.log("=== Step 6: bank fix ===");
    await api("PUT", `/ledger/account/${acc1920.id}`, {
      ...acc1920,
      bankAccountNumber: "12345678903",
    });
    acc1920.bankAccountNumber = "12345678903";
  } else {
    console.log("=== Step 6: no bank fix needed ===");
  }

  // Step 7: invoice (1)
  console.log("=== Step 7: invoice ===");
  const invoiceRes = await api("POST", "/invoice?sendToCustomer=false", {
    invoiceDate: TODAY,
    invoiceDueDate: "2026-04-20",
    customer: { id: customerId },
    orders: [
      {
        customer: { id: customerId },
        project: { id: projectId },
        orderDate: TODAY,
        deliveryDate: TODAY,
        orderLines: [
          {
            description: `OptProject ${RND} - Prosjekttjenester`,
            count: 1,
            unitPriceExcludingVatCurrency: 229500,
            vatType: { id: vatType.id },
          },
        ],
      },
    ],
  });

  console.log("\n=== RESULTS ===");
  console.log("Total API calls:", callCount);
  console.log("Errors:", errorCount);
  console.log("Invoice id:", invoiceRes.value.id);
  console.log("Invoice number:", invoiceRes.value.invoiceNumber);
  console.log("amountExcludingVat:", invoiceRes.value.amountExcludingVatCurrency);
  console.log("projectInvoiceDetails:", invoiceRes.value.projectInvoiceDetails?.length);
  console.log("voucherId:", voucherRes.value.id);
  console.log("supplierId:", suppId);
}

main().catch(e => { console.error("FATAL:", e.message); process.exit(1); });

